import { test, expect } from '@playwright/test';

test.describe('Error Boundary - UI Crash Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display error boundary fallback screen when component crashes', async ({ page }) => {
    // Navigate to a page that will trigger an error in a component
    await page.goto('http://localhost:3000/error-trigger');

    // Verify that the error boundary fallback UI is displayed
    const fallbackHeading = page.getByRole('heading', { name: /something went wrong/i });
    await expect(fallbackHeading).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/an unexpected error occurred/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should show error details in fallback screen', async ({ page }) => {
    await page.goto('http://localhost:3000/error-trigger');

    // Verify error details section exists
    const errorDetails = page.getByRole('region', { name: /error details/i });
    await expect(errorDetails).toBeVisible();

    // Verify error message contains specific error information
    const errorText = page.getByText(/component failed to render/i);
    await expect(errorText).toBeVisible();
  });

  test('should provide recovery action button in error boundary', async ({ page }) => {
    await page.goto('http://localhost:3000/error-trigger');

    // Verify recovery button is present
    const recoveryButton = page.getByRole('button', { name: /try again|reload|reset/i });
    await expect(recoveryButton).toBeVisible();

    // Click recovery button
    await recoveryButton.click();

    // Verify page recovers or navigates appropriately
    await expect(page).toHaveURL(/http:\/\/localhost:3000/);
  });

  test('should maintain error boundary across navigation', async ({ page }) => {
    // Navigate to normal page first
    await page.goto('http://localhost:3000/dashboard');

    // Verify normal content is displayed
    const normalContent = page.getByRole('main');
    await expect(normalContent).toBeVisible();

    // Navigate to error page
    await page.goto('http://localhost:3000/error-trigger');

    // Verify error boundary is active
    const fallbackScreen = page.getByRole('heading', { name: /something went wrong/i });
    await expect(fallbackScreen).toBeVisible();
  });

  test('should display error boundary without breaking page layout', async ({ page }) => {
    await page.goto('http://localhost:3000/error-trigger');

    // Verify error boundary container is properly rendered
    const errorContainer = page.getByRole('region', { name: /error boundary|error screen/i });
    await expect(errorContainer).toBeVisible();

    // Verify page is still interactive
    const buttons = page.getByRole('button');
    const buttonCount = await buttons.count();
    expect(buttonCount).toBeGreaterThan(0);
  });

  test('should log error information for debugging', async ({ page }) => {
    // Listen for console messages
    const consoleLogs: string[] = [];
    page.on('console', msg => {
      if (msg.type() === 'error') {
        consoleLogs.push(msg.text());
      }
    });

    await page.goto('http://localhost:3000/error-trigger');

    // Verify error boundary is displayed
    const fallbackHeading = page.getByRole('heading', { name: /something went wrong/i });
    await expect(fallbackHeading).toBeVisible();

    // Verify error was logged (if error logging is implemented)
    // This depends on the application's error logging implementation
    await page.waitForTimeout(500);
  });
});
